/* Every on-screen string of the management window, in English and Thai (roadmap entry 2, "Language EN | ไทย").
   Both tables have the same keys; a key missing from `th` falls back to English (`language.cjs` checks parity).
   Strings with values are functions, so each language keeps its own word order. Strings that return markup escape
   the values they insert; everything else is plain text that the caller escapes. Wording: see the on-screen
   wording table (Master, Tag, Merge and SSH stay in English in both languages). */
export const esc = value => String(value ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const plural = (n, one, many) => n + " " + (n === 1 ? one : many);

